// js
// 工资支付暂行规定 第十一条、第十二条: no wage for days not worked. A fixed allowance is paid for the days BASIC pays, so it falls and returns with the no-pay lines there, and BASIC stays the salary alone.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const rate = Number(get(terms, 'rate.amount', 0));
const amount = Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
const coverage = ctx.run.salary_coverage;
const off = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
let working = 0;
for (let date = coverage.from; date <= coverage.to; date = add_days(date, 1)) if (!off.includes(weekday(date))) working += 1;
const hours = Number(get(terms, 'normal_hours_per_month', working * Number(get(terms, 'normal_hours_per_day', 8))));
const salary = unit === 'DAILY' ? rate * working : unit === 'HOURLY' ? rate * hours : rate;
return salary > 0 ? (amount * ctx.subtotals.BASIC) / salary : amount;

eligibility:
if (get(ctx.subject.employer, 'entity_extension_data.region', '') !== ctx.lookup.region) return false;
if (get(ctx.subject.employment, 'employee_extension_data.high_temperature_exposed', false) !== true) return false;
return ctx.lookup.months.includes(Number(ctx.as_of.slice(5, 7)));
